$ErrorActionPreference='Stop';$rows=([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))|ConvertFrom-Json);function State {$l=@(Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue|Where-Object {$_.LocalPort -in @(9600,8091)});[ordered]@{at=(Get-Date).ToUniversalTime().ToString('o');nodeTask=(Get-ScheduledTask -TaskPath '\Enclave\' -TaskName 'Node').State.ToString();listeners=@($l|Select-Object LocalAddress,LocalPort,OwningProcess)}};function CheckTask {$t=Get-ScheduledTask -TaskPath '\Enclave\' -TaskName 'Node';$x=@($t.Actions);if($x.Count -ne 1 -or $x[0].Execute -ne 'cmd.exe' -or $x[0].Arguments -ne '/c "C:\ProgramData\Enclave\run-node.cmd"'){throw 'Unexpected Node scheduled task'}};function CheckFiles($key){foreach($r in $rows){if((FileSha $r.live) -ne $r.$key){throw ('live source changed: '+$r.rel)}}};function Staged {foreach($r in $rows){if((FileSha $r.stage) -ne $r.after){throw ('staged source changed: '+$r.rel)};& 'C:\Program Files\Enclave\runtime\node\node.exe' --check $r.stage;if($LASTEXITCODE -ne 0){throw ('native syntax failed: '+$r.rel)}}};function Stopped {CheckTask;$s=State;if($s.nodeTask -eq 'Running' -or @($s.listeners|Where-Object {$_.LocalPort -eq 9600}).Count -ne 0){throw 'Node still active'};if(@($s.listeners|Where-Object {$_.LocalPort -eq 8091}).Count -ne 1){throw 'Shield listener changed'}};
$shieldNow=@((State).listeners|Where-Object {$_.LocalPort -eq 8091});if($shieldNow.Count -ne 1 -or $shieldNow[0].OwningProcess -ne 2376){throw 'Shield restarted since preflight; inspect before proceeding'};try {CheckFiles 'after';$a=Invoke-RestMethod -TimeoutSec 8 http://127.0.0.1:9600/availability;$h=Invoke-RestMethod -TimeoutSec 8 http://127.0.0.1:9600/v1/host/state;$v=Invoke-RestMethod -TimeoutSec 8 http://127.0.0.1:8091/vms;@{ok=$true;state=(State);availability=$a|Select-Object nodeRamGb,ramGbFree,ramMbFree,cpuShareFree,maxShare;deployments=@($h.deployments|Select-Object id,status,reason,cpuShare,memMb);vms=@($v.vms|Select-Object id,name,status,memory)}|ConvertTo-Json -Depth 7 -Compress}catch{@{ok=$false;error=$_.Exception.Message}|ConvertTo-Json -Compress}
